from __future__ import annotations

import typing as t

from sqlglot import exp
from sqlglot.helper import name_sequence, seq_get
from sqlglot.optimizer.scope import Scope, find_all_in_scope, traverse_scope

if t.TYPE_CHECKING:
    from sqlglot._typing import E


def canonicalize_internal_names(expression: E) -> E:
    """
    Rewrite a query to a canonical structural form.

    Preserves data-contract names (base-table names and columns, top-level output
    aliases) and canonicalizes internal names (table aliases, CTE/subquery names,
    internal column aliases) to sequential `_tN` / `_cN`. For set operations the
    top-level output is the leftmost leaf SELECT.

    Assumes the expression has already been processed by `qualify` (or equivalent),
    so that columns are bound to sources and aliases exist on every projection /
    subquery / CTE.

    Example:
        >>> import sqlglot
        >>> from sqlglot.optimizer.qualify import qualify
        >>> schema = {"src": {"c1": "INT", "c2": "INT"}}
        >>> canonicalize_internal_names(qualify(sqlglot.parse_one("WITH t AS (SELECT c1, c2 FROM c.db.src) SELECT * FROM t"), schema=schema)).sql()
        'WITH "_t1" AS (SELECT "_t0"."c1" AS "_c0", "_t0"."c2" AS "_c1" FROM "c"."db"."src" AS "_t0") SELECT "_t1"."_c0" AS "c1", "_t1"."_c1" AS "c2" FROM "_t1" AS "_t1"'
    """
    # Skip non-queries for now (e.g., UPDATE ... SET x = s.x FROM (SELECT ...) AS s)
    if not isinstance(expression, exp.Query):
        return expression

    # Top-level output scopes: their aliases are the query's data contract. Regular UNION takes names
    # from the left branch; UNION BY NAME takes names from the union of all branches, so both sides of
    # a by_name SetOperation contribute.
    output_scope_exprs: set[int] = set()
    stack: list[exp.Expr] = [expression]
    while stack:
        node = stack.pop()
        if isinstance(node, exp.SetOperation):
            # Access the args directly instead of the left/right properties, because set operation
            # operands aren't guaranteed to be Query nodes, e.g. in VALUES (1) UNION ALL SELECT 1
            stack.append(node.this.unnest())
            if node.args.get("by_name"):
                stack.append(node.expression.unnest())
        else:
            output_scope_exprs.add(id(node))

    next_table = name_sequence("_t")
    next_column = name_sequence("_c")

    def _canon(ident: exp.Identifier, name: str) -> None:
        ident.set("this", name)
        ident.set("quoted", True)

    scope_table: dict[int, str] = {}
    scope_outputs: dict[int, dict[str, str]] = {}

    # Shared across scopes so a Table referenced from multiple scopes (LATERAL/UNNEST) gets consistent column names
    table_columns: dict[int, dict[str, str]] = {}

    # Shared across UDTF sources so chained correlated UNNESTs get consistent names for their alias columns
    udtf_columns: dict[int, dict[str, str]] = {}

    for scope in traverse_scope(expression):
        scope_expr = scope.expression
        is_output_scope = id(scope_expr) in output_scope_exprs

        columns_by_source: dict[str, list[exp.Column | exp.TableColumn]] = {}
        for col in scope.columns:
            columns_by_source.setdefault(col.table, []).append(col)
        for table_col in scope.table_columns:
            columns_by_source.setdefault(table_col.name, []).append(table_col)

        # Include qualified stars (e.g. `t.*`)
        for star in scope.stars:
            if isinstance(star, exp.Column) and star.table:
                columns_by_source.setdefault(star.table, []).append(star)

        # source_canon: source's canonical name (used in WITH "_tN" AS, and as
        #   the physical table name in `Table.this`). Shared across every reference
        #   to the same source within this scope.
        # ref_alias:   per-reference canonical alias (used as the alias on each
        #   `Table` node and as the qualifier on its column refs). The first
        #   reference reuses source_canon for compactness; subsequent refs get
        #   fresh `_tN` names so a self-join like `cte AS x JOIN cte AS y`
        #   produces unique aliases.
        table_map: dict[str, tuple[str, str]] = {}
        ref_canon_taken: set[str] = set()

        for source_name, source in scope.sources.items():
            source_cols = columns_by_source.get(source_name, [])

            alias_holder: exp.Expr | None = None
            is_base_source = isinstance(source, exp.Table)

            if is_base_source:
                canon_t = scope_table.get(id(source), "")
                if not canon_t:
                    canon_t = next_table()
                    scope_table[id(source)] = canon_t
                child_output: dict[str, str] = {}
                name_map: dict[str, str] = table_columns.setdefault(id(source), {})
            elif isinstance(source, Scope):
                # Key by id(expression) so a recursive CTE's self-reference, i.e., a separate
                # Scope whose `expression` is the same object as the CTE's base branch, shares
                # the base branch's output mapping.
                src_expr = source.expression
                child_output = scope_outputs.get(id(src_expr), {})

                parent = src_expr.parent
                if isinstance(parent, (exp.CTE, exp.Subquery)):
                    alias_holder = parent
                elif (
                    isinstance(parent, exp.SetOperation)
                    and isinstance(cte := parent.parent, exp.CTE)
                    and isinstance(with_ := cte.parent, exp.With)
                    and with_.recursive
                ):
                    alias_holder = cte
                elif source.is_udtf:
                    alias_holder = src_expr

                # A UDTF (unlike a CTE/subquery) can be a source in multiple scopes, so keep its alias_holder and share its column map across them
                is_udtf_source = alias_holder is src_expr

                table_key = id(alias_holder) if alias_holder else id(source)
                canon_t = scope_table.get(table_key, "")

                if not canon_t:
                    canon_t = next_table()
                    scope_table[table_key] = canon_t
                elif not is_udtf_source:
                    alias_holder = None  # already renamed on a previous encounter

                name_map = udtf_columns.setdefault(id(src_expr), {}) if is_udtf_source else {}
            else:
                continue

            if canon_t in ref_canon_taken:
                ref_alias = next_table()
            else:
                ref_alias = canon_t
                ref_canon_taken.add(canon_t)

            table_map[source_name] = (canon_t, ref_alias)

            # UNNEST struct fields are physical columns (preserve); the element alias is not
            struct_field_names: set[str] = set()
            src = source.expression
            if (
                isinstance(src, exp.Unnest)
                and src.expressions
                and src.expressions[0].type
                and (element_type := seq_get(src.expressions[0].type.expressions, 0))
                and element_type.is_type(exp.DataType.Type.STRUCT)
            ):
                struct_field_names = {cd.name for cd in element_type.expressions}

            for src_col in source_cols:
                # BigQuery whole-row struct ref (`SELECT t FROM t`): the identifier
                # IS the table alias, so rename it to this reference's alias.
                if isinstance(src_col, exp.TableColumn):
                    _canon(src_col.this, ref_alias)
                    continue

                old_name = src_col.name
                preserve_col = is_base_source or old_name in struct_field_names
                canon_col = name_map.get(old_name)

                if canon_col is None:
                    if preserve_col:
                        canon_col = old_name
                    else:
                        canon_col = child_output.get(old_name) or next_column()

                    name_map[old_name] = canon_col

                # Base-table and UNNEST struct-field column refs name physical columns => preserve
                # verbatim (including quote state). Scope-sourced refs are internal handles pointing
                # at CTE/subquery aliases (injected unquoted via exp.to_identifier), so _canon them.
                if not preserve_col:
                    _canon(src_col.this, canon_col)

                table_id = src_col.args.get("table")
                if table_id:
                    _canon(table_id, ref_alias)

            if alias_holder:
                if alias := alias_holder.args.get("alias"):
                    if isinstance(alias.this, exp.Identifier):
                        # The CTE/Subquery name itself uses source_canon (canon_t),
                        # not ref_alias — it's the source's identity, not a reference.
                        _canon(alias.this, canon_t)
                    if alias.columns:
                        alias.set(
                            "columns",
                            [
                                exp.to_identifier(name_map.get(c.name, c.name), quoted=c.quoted)
                                for c in alias.columns
                            ],
                        )

                # UNNEST stores its offset column outside the alias, including under LATERAL.
                unnest = (
                    alias_holder.this if isinstance(alias_holder, exp.Lateral) else alias_holder
                )
                if isinstance(unnest, exp.Unnest):
                    offset_id = unnest.args.get("offset")
                    if isinstance(offset_id, exp.Identifier) and offset_id.name in name_map:
                        _canon(offset_id, name_map[offset_id.name])

        # PIVOT output column names are bound to the IN-clause literals, so only the
        # alias (which qualifies column refs like `my_pivot.x`) is canonicalized.
        for pivot in scope.pivots:
            pivot_alias = pivot.args.get("alias")
            if not (pivot_alias and isinstance(pivot_alias.this, exp.Identifier)):
                continue
            pivot_cols = columns_by_source.get(pivot_alias.this.name)
            if not pivot_cols:
                continue

            canon_t = next_table()
            _canon(pivot_alias.this, canon_t)

            for pivot_col in pivot_cols:
                table_id = pivot_col.args.get("table")
                if table_id:
                    _canon(table_id, canon_t)

        for table in scope.tables:
            entry = table_map.get(table.alias_or_name)
            if not entry:
                continue
            source_canon, ref_alias = entry

            # Real tables (qualified with db/catalog) keep their physical name;
            # CTE/subquery references get the source's canonical `_tN`.
            if isinstance(table.this, exp.Identifier) and not table.args.get("db"):
                _canon(table.this, source_canon)

            alias = table.args.get("alias")
            if alias:
                # The reference alias uses ref_alias, which is unique per Table
                # node so multiple references to the same source can coexist.
                if isinstance(alias.this, exp.Identifier):
                    _canon(alias.this, ref_alias)
                if alias.columns:
                    tc = table_columns.get(id(table), {})
                    alias.set(
                        "columns",
                        [
                            exp.to_identifier(tc.get(c.name, c.name), quoted=c.quoted)
                            for c in alias.columns
                        ],
                    )

        output_map: dict[str, str] = {}
        if isinstance(scope_expr, exp.Select):
            for sel in scope_expr.selects:
                # Sets default name for subquery projections, both aliased and unaliased
                if isinstance(sel, (exp.Alias, exp.Subquery)) and sel.alias:
                    old_alias = sel.alias
                    if is_output_scope:
                        new_name = old_alias
                    else:
                        new_name = next_column()
                        sel.set("alias", exp.to_identifier(new_name, quoted=True))

                    output_map[old_alias] = new_name
        elif isinstance(scope_expr, exp.SetOperation) and scope.set_operation_scopes:
            # Regular UNION names come from the left branch. UNION BY NAME folds
            # in right-branch names too (any column unique to the right still
            # appears in the output).
            output_map = scope_outputs.get(id(scope.set_operation_scopes[0].expression), {}).copy()
            if scope_expr.args.get("by_name"):
                right_out = scope_outputs.get(id(scope.set_operation_scopes[1].expression), {})
                for k, v in right_out.items():
                    output_map.setdefault(k, v)
        elif scope.is_udtf and scope.subquery_scopes:
            output_map = scope_outputs.get(id(scope.subquery_scopes[0].expression), {}).copy()

        scope_outputs[id(scope_expr)] = output_map

        # Unqualified alias references (ORDER BY a, HAVING a > 5, ...)
        for col in find_all_in_scope(scope_expr, exp.Column):
            if not col.table and col.name in output_map:
                _canon(col.this, output_map[col.name])

        # UBN matches branches by original alias. When both branches are internal
        # and aliased to distinct _cN, matching originals land on different slots
        # and UBN splits them into disjoint output columns, dropping data. Align
        # the right branch's canonicals to the left's. No-op when both branches
        # preserved their aliases (top-level UBN).
        if isinstance(scope_expr, exp.SetOperation) and scope_expr.args.get("by_name"):
            left_scope, right_scope = scope.set_operation_scopes
            left_out = scope_outputs.get(id(left_scope.expression), {})
            right_out = scope_outputs.get(id(right_scope.expression), {})

            rename: dict[str, str] = {}
            for orig_name, left_canon in left_out.items():
                right_canon = right_out.get(orig_name)
                if right_canon and right_canon != left_canon:
                    rename[right_canon] = left_canon

            if rename:
                rename_stack: list[exp.Expr] = [right_scope.expression]
                while rename_stack:
                    node = rename_stack.pop()
                    if isinstance(node, exp.Select):
                        for sel in node.selects:
                            if isinstance(sel, exp.Alias):
                                aid = sel.args.get("alias")
                                if isinstance(aid, exp.Identifier) and aid.name in rename:
                                    _canon(aid, rename[aid.name])
                    elif isinstance(node, exp.SetOperation):
                        rename_stack.append(node.this.unnest())
                        rename_stack.append(node.expression.unnest())
                    else:
                        continue

                    for col in find_all_in_scope(node, exp.Column):
                        if not col.table and col.name in rename:
                            _canon(col.this, rename[col.name])

                scope_outputs[id(right_scope.expression)] = {
                    k: rename.get(v, v) for k, v in right_out.items()
                }

    return expression

sqlglot/optimizer/eliminate_joins.py.source:
from __future__ import annotations

import typing as t

from sqlglot import expressions as exp
from sqlglot.optimizer.normalize import normalized
from sqlglot.optimizer.scope import Scope, find_in_scope, traverse_scope

if t.TYPE_CHECKING:
    from sqlglot._typing import E


def eliminate_joins(expression: E) -> E:
    """
    Remove unused joins from an expression.

    This only removes joins when we know that the join condition doesn't produce duplicate rows.

    Example:
        >>> import sqlglot
        >>> sql = "SELECT x.a FROM x LEFT JOIN (SELECT DISTINCT y.b FROM y) AS y ON x.b = y.b"
        >>> expression = sqlglot.parse_one(sql)
        >>> eliminate_joins(expression).sql()
        'SELECT x.a FROM x'

    Args:
        expression: expression to optimize

    Returns:
        The optimized expression
    """
    for scope in traverse_scope(expression):
        joins: list[exp.Join] = scope.expression.args.get("joins", [])
        if not joins:
            continue

        # If any columns in this scope aren't qualified, it's hard to determine if a join isn't used.
        # It's probably possible to infer this from the outputs of derived tables.
        # But for now, let's just skip this rule.
        if scope.unqualified_columns:
            continue

        # Reverse the joins so we can remove chains of unused joins
        for join in reversed(joins):
            if (
                join.is_semi_or_anti_join
                or join.method == "POSITIONAL"
                or join.kind == "PASTE"
                or join.args.get("nearest")
            ):
                continue

            alias = join.alias_or_name
            if _should_eliminate_join(scope, join, alias):
                join.pop()
                scope.remove_source(alias)

    return expression


def _should_eliminate_join(scope: Scope, join: exp.Join, alias: str) -> bool:
    inner_source = scope.sources.get(alias)
    return (
        isinstance(inner_source, Scope)
        and not _join_is_used(scope, join, alias)
        and (
            (join.side == "LEFT" and _is_joined_on_all_unique_outputs(inner_source, join))
            or (
                not join.side
                and not join.method
                and not join.args.get("on")
                and not join.args.get("using")
                and not join.args.get("match_condition")
                and _has_single_output_row(inner_source)
            )
        )
    )


def _join_is_used(scope: Scope, join: exp.Join, alias: str) -> bool:
    # We need to find all columns that reference this join.
    # But columns in the ON clause shouldn't count.
    on: exp.Expr | None = join.args.get("on")
    if on is not None:
        on_clause_columns: set[int] = {id(column) for column in on.find_all(exp.Column)}
    else:
        on_clause_columns = set()
    return any(
        column for column in scope.source_columns(alias) if id(column) not in on_clause_columns
    )


def _is_joined_on_all_unique_outputs(scope: Scope, join: exp.Join) -> bool:
    unique_outputs = _unique_outputs(scope)
    if not unique_outputs:
        return False

    _, join_keys, _ = join_condition(join)

    # we check for columns because transformations can map distinct values to the same join key
    remaining_unique_outputs = unique_outputs - {
        c.name for c in join_keys if isinstance(c, exp.Column)
    }
    return not remaining_unique_outputs


def _unique_outputs(scope: Scope) -> set[str]:
    """Determine output columns of `scope` that must have a unique combination per row"""
    expr = t.cast(exp.Query, scope.expression)
    # Set operations store a bool here, which is False for UNION ALL, INTERSECT ALL and EXCEPT ALL
    if (distinct := expr.args.get("distinct")) and not (
        isinstance(distinct, exp.Distinct) and distinct.args.get("on")
    ):
        return set(expr.named_selects)

    group: exp.Group | None = expr.args.get("group")
    if group is not None:
        grouped_expressions: set[exp.Expr] = set(group.expressions)
        grouped_outputs: set[exp.Expr] = set()

        unique_outputs: set[str] = set()
        for select in expr.selects:
            output = select.unalias()
            if output in grouped_expressions:
                grouped_outputs.add(output)
                unique_outputs.add(select.alias_or_name)

        # All the grouped expressions must be in the output
        if not grouped_expressions.difference(grouped_outputs):
            return unique_outputs
        else:
            return set()

    if _is_limit_1(scope) or _has_single_output_row(scope):
        return set(expr.named_selects)

    return set()


def _has_single_output_row(scope: Scope) -> bool:
    expression = scope.expression
    if not isinstance(expression, exp.Select):
        return False

    args = expression.args
    if any(args.get(key) for key in ("group", "having", "qualify", "limit", "offset")):
        return False
    if args.get("from_") or args.get("where"):
        return all(isinstance(select.unalias(), exp.AggFunc) for select in expression.selects)
    return not any(
        find_in_scope(select, *exp.SET_RETURNING_FUNCTIONS) for select in expression.selects
    )


def _is_limit_1(scope: Scope) -> bool:
    limit = scope.expression.args.get("limit")
    return isinstance(limit, exp.Limit) and limit.expression.this == "1"


def join_condition(join: exp.Join) -> tuple[list[exp.Expr], list[exp.Expr], exp.Expr]:
    """
    Extract the join condition from a join expression.

    Args:
        join (exp.Join)
    Returns:
        tuple[list[str], list[str], exp.Expr]:
            Tuple of (source key, join key, remaining predicate)
    """
    name = join.alias_or_name
    on: exp.Expr = (join.args.get("on") or exp.true()).copy()
    source_key: list[exp.Expr] = []
    join_key: list[exp.Expr] = []

    def extract_condition(condition: exp.Expr) -> None:
        left, right = condition.unnest_operands()
        left_tables = exp.column_table_names(left)
        right_tables = exp.column_table_names(right)

        if name in left_tables and name not in right_tables:
            join_key.append(left)
            source_key.append(right)
            condition.replace(exp.true())
        elif name in right_tables and name not in left_tables:
            join_key.append(right)
            source_key.append(left)
            condition.replace(exp.true())

    # find the join keys
    # SELECT
    # FROM x
    # JOIN y
    #   ON x.a = y.b AND y.b > 1
    #
    # should pull y.b as the join key and x.a as the source key
    if normalized(on):
        on = on if isinstance(on, exp.And) else exp.and_(on, exp.true(), copy=False)

        for condition in on.flatten():
            if isinstance(condition, exp.EQ):
                extract_condition(condition)
    elif normalized(on, dnf=True):
        conditions: list[exp.EQ] = []

        for condition in on.flatten():
            parts = [part for part in condition.flatten() if isinstance(part, exp.EQ)]
            if not conditions:
                conditions = parts
            else:
                temp: list[exp.EQ] = []
                for p in parts:
                    cs = [c for c in conditions if p == c]

                    if cs:
                        temp.append(p)
                        temp.extend(cs)
                conditions = temp

        for condition in conditions:
            extract_condition(condition)

    return source_key, join_key, on

