from sqlglot import ErrorLevel, UnsupportedError, exp, parse_one
from sqlglot.generator import logger as generator_logger
from sqlglot.helper import logger as helper_logger
from sqlglot.optimizer.annotate_types import annotate_types
from tests.dialects.test_dialect import Validator


class TestPresto(Validator):
    dialect = "presto"

    def test_approx_percentile(self):
        expression = self.validate_identity("APPROX_PERCENTILE(x, 0.5, 0.01)")
        self.assertEqual(expression.args["quantile"], exp.Literal.number("0.5"))
        self.assertEqual(expression.args["accuracy"], exp.Literal.number("0.01"))
        self.assertIsNone(expression.args.get("weight"))
        self.validate_all(
            "APPROX_PERCENTILE(x, 0.5, 0.01)",
            write={"bigquery": "APPROX_QUANTILES(x, 2)[1]"},
        )

    def test_temporal_precision(self):
        message = "Presto only supports millisecond precision for temporal types"
        for kind, value in (("TIMESTAMP", "2020-01-01 00:00:00"), ("TIME", "12:00:00")):
            for zone in ("", " +02:00"):
                suffix = " WITH TIME ZONE" if zone else ""
                expected = f"CAST('{value}.123{zone}' AS {kind}{suffix})"
                for precision in ("", "(0)", "(1)", "(2)", "(3)", "(6)"):
                    with self.subTest(kind=kind, zone=zone, precision=precision):
                        expression = parse_one(
                            f"CAST('{value}.123{zone}' AS {kind}{precision}{suffix})",
                            read="trino",
                        )
                        if precision in ("", "(3)"):
                            self.assertEqual(
                                expression.sql("presto", unsupported_level=ErrorLevel.RAISE),
                                expected,
                            )
                        else:
                            with self.assertLogs(generator_logger) as logs:
                                self.assertEqual(expression.sql("presto"), expected)
                            self.assertIn(message, logs.output[0])
                            with self.assertRaisesRegex(UnsupportedError, message):
                                expression.sql("presto", unsupported_level=ErrorLevel.RAISE)

    def test_cast(self):
        self.validate_identity("DEALLOCATE PREPARE my_query", check_command_warning=True)
        self.validate_identity("DESCRIBE INPUT x", check_command_warning=True)
        self.validate_identity("DESCRIBE OUTPUT x", check_command_warning=True)
        self.validate_identity("SELECT * FROM x qualify", "SELECT * FROM x AS qualify")
        self.validate_identity("CAST(x AS IPADDRESS)")
        self.validate_identity("CAST(x AS IPPREFIX)")
        self.validate_identity("CAST(TDIGEST_AGG(1) AS TDIGEST)")
        self.validate_identity("CAST(x AS HYPERLOGLOG)")
