from sqlglot import parse_one, exp
from sqlglot.optimizer.qualify import qualify
from tests.dialects.test_dialect import Validator


class TestSingleStore(Validator):
    dialect = "singlestore"

    def test_singlestore(self):
        ast = parse_one(
            "SELECT id AS my_id FROM data WHERE my_id = 1 GROUP BY my_id HAVING my_id = 1",
            dialect=self.dialect,
        )
        ast = qualify(ast, dialect=self.dialect, schema={"data": {"id": "INT", "my_id": "INT"}})
        self.assertEqual(
            "SELECT `data`.`id` AS `my_id` FROM `data` AS `data` WHERE `data`.`my_id` = 1 GROUP BY `data`.`my_id` HAVING `data`.`id` = 1",
            ast.sql(dialect=self.dialect),
        )

        self.validate_identity("SELECT 1")
        self.validate_identity("SELECT * FROM `users` ORDER BY ALL")
        self.validate_identity("SELECT ELT(2, 'foo', 'bar', 'baz')")
        self.validate_identity("SELECT CHARSET(CHAR(100 USING utf8))")
        self.validate_identity("SELECT TO_JSON(ROW(1, 2) :> RECORD(a INT, b INT))")

        self.validate_identity("JSON_KEYS(json_doc, 'a', 'b', 'c', 2)")
        self.validate_identity("SELECT VERSION()")
        self.validate_identity("SELECT CURTIME()", "SELECT CURRENT_TIME()")

    def test_byte_strings(self):
        self.validate_identity("SELECT e'text'")
        self.validate_identity("SELECT E'text'", "SELECT e'text'")

    def test_percentile_null_ordering(self):
        for func in ("PERCENTILE_CONT", "PERCENTILE_DISC"):
            self.validate_all(
                f"SELECT {func}(0.75) WITHIN GROUP (ORDER BY x) FROM t",
                read={
                    "postgres": f"SELECT {func}(0.75) WITHIN GROUP (ORDER BY x) FROM t",
                    "singlestore": f"SELECT {func}(0.75) WITHIN GROUP (ORDER BY x NULLS LAST) FROM t",
                },
            )
            self.validate_all(
                f"SELECT {func}(0.75) WITHIN GROUP (ORDER BY x DESC NULLS FIRST) OVER (PARTITION BY g) FROM t",
                read={
                    "postgres": f"SELECT {func}(0.75) WITHIN GROUP (ORDER BY x DESC) OVER (PARTITION BY g) FROM t",
                    "singlestore": f"SELECT {func}(0.75) WITHIN GROUP (ORDER BY x DESC NULLS LAST) OVER (PARTITION BY g) FROM t",
                },
            )

        self.validate_all(
            "SELECT PERCENTILE_CONT(1) WITHIN GROUP (ORDER BY x) FROM t ORDER BY x NULLS LAST",
            read={
                "postgres": "SELECT PERCENTILE_CONT(1) WITHIN GROUP (ORDER BY x) FROM t ORDER BY x",
            },
        )

    def test_national_strings(self):
        self.validate_all(
            "SELECT 'text'", read={"": "SELECT N'text'", "singlestore": "SELECT 'text'"}
        )

    def test_restricted_keywords(self):
        self.validate_identity("SELECT * FROM abs", "SELECT * FROM `abs`")
        self.validate_identity("SELECT * FROM ABS", "SELECT * FROM `ABS`")
        self.validate_identity(
