    def test_lateral_view_outer(self):
        for sql in (
            "SELECT a FROM x LATERAL VIEW OUTER EXPLODE(y) t AS a",
            "SELECT a FROM x LATERAL VIEW EXPLODE_OUTER(y) t AS a",
        ):
            with self.subTest(sql):
                self.validate_all(
                    sql,
                    write={
                        "athena": "SELECT a FROM x LEFT JOIN UNNEST(y) AS t(a) ON TRUE",
                        "duckdb": "SELECT a FROM x LEFT JOIN UNNEST(y) AS t(a) ON TRUE",
                        "presto": "SELECT a FROM x CROSS JOIN UNNEST(y) AS t(a)",
                        "trino": "SELECT a FROM x LEFT JOIN UNNEST(y) AS t(a) ON TRUE",
                        "spark": sql,
                    },
                )
                with self.assertRaises(UnsupportedError):
                    self.parse_one(sql).sql("presto", unsupported_level=ErrorLevel.RAISE)

        for sql in (
            "SELECT a FROM x LATERAL VIEW OUTER POSEXPLODE(y) t AS pos, col",
            "SELECT a FROM x LATERAL VIEW POSEXPLODE_OUTER(y) t AS pos, col",
        ):
            with self.subTest(sql):
                self.validate_all(
                    sql,
                    write={
                        "duckdb": "SELECT a FROM x LEFT JOIN LATERAL (SELECT pos - 1 AS pos, col FROM UNNEST(y) WITH ORDINALITY AS t(col, pos)) ON TRUE",
                        "presto": "SELECT a FROM x CROSS JOIN LATERAL (SELECT pos - 1 AS pos, col FROM UNNEST(y) WITH ORDINALITY AS t(col, pos))",
                        "trino": "SELECT a FROM x LEFT JOIN LATERAL (SELECT pos - 1 AS pos, col FROM UNNEST(y) WITH ORDINALITY AS t(col, pos)) ON TRUE",
                        "spark": sql,
                    },
                )

        self.validate_all(
            "SELECT a, b FROM x LATERAL VIEW OUTER INLINE(y) t AS a, b",
            write={
                "duckdb": "SELECT a, b FROM x LEFT JOIN LATERAL (SELECT UNNEST(y, max_depth => 2)) AS t(a, b) ON TRUE",
                "presto": "SELECT a, b FROM x CROSS JOIN UNNEST(y) AS t(a, b)",
                "trino": "SELECT a, b FROM x LEFT JOIN UNNEST(y) AS t(a, b) ON TRUE",
                "spark": "SELECT a, b FROM x LATERAL VIEW OUTER INLINE(y) t AS a, b",
            },
        )

    def test_explode_map(self):
        from sqlglot.optimizer.annotate_types import annotate_types
        from sqlglot.optimizer.qualify import qualify

        expression = annotate_types(self.parse_one("SELECT EXPLODE(MAP(1, 'a')) AS (k, v)"))
        self.assertEqual(
            expression.sql("presto"),
            "SELECT _u_2.k AS k, _u_2.v AS v FROM UNNEST(MAP(ARRAY[1], ARRAY['a'])) AS _u_2(k, v)",
        )

        schema = {"tbl": {"cells": "MAP<INT, STRING>"}}
        expression = qualify(
            self.parse_one("SELECT EXPLODE(cells) AS (cell_id, cell_name) FROM tbl"),
            dialect="spark",
            schema=schema,
        )
        expression = annotate_types(expression, dialect="spark", schema=schema)
        self.assertEqual(
            expression.sql("trino"),
            'SELECT _u_2."cell_id" AS "cell_id", _u_2."cell_name" AS "cell_name" FROM "tbl" AS "tbl" CROSS JOIN UNNEST("tbl"."cells") AS _u_2("cell_id", "cell_name")',
        )

        expression = annotate_types(
            self.parse_one("SELECT EXPLODE(tbl.cells) FROM tbl"),
            dialect="spark",
            schema=schema,
        )
        self.assertEqual(
            expression.sql("trino"),
            "SELECT _u_2.key AS key, _u_2.value AS value FROM tbl CROSS JOIN UNNEST(tbl.cells) AS _u_2(key, value)",
        )

    def test_strip_modifiers(self):
        without_modifiers = "SELECT * FROM t"
        with_modifiers = f"{without_modifiers} CLUSTER BY y DISTRIBUTE BY x SORT BY z"
        query = self.parse_one(with_modifiers)

        for dialect in Dialects:
            with self.subTest(f"Transpiling query with CLUSTER/DISTRIBUTE/SORT BY to {dialect}"):
                name = dialect.value
                if name in ("", "databricks", "hive", "spark", "spark2"):
                    self.assertEqual(query.sql(name), with_modifiers)
                else:
                    self.assertEqual(query.sql(name), without_modifiers)

    def test_schema_binding_options(self):
        for schema_binding in (
            "BINDING",
            "COMPENSATION",
            "TYPE EVOLUTION",
            "EVOLUTION",
        ):
            with self.subTest(f"Test roundtrip of VIEW schema binding {schema_binding}"):
                self.validate_identity(
                    f"CREATE VIEW emp_v WITH SCHEMA {schema_binding} AS SELECT * FROM emp"
                )

    def test_minus(self):
        self.validate_all(
            "SELECT * FROM db.table1 MINUS SELECT * FROM db.table2",
            write={
                "spark": "SELECT * FROM db.table1 EXCEPT SELECT * FROM db.table2",
                "databricks": "SELECT * FROM db.table1 EXCEPT SELECT * FROM db.table2",
            },
        )

    def test_string(self):
        for dialect in ("hive", "spark2", "spark", "databricks"):
            with self.subTest(f"Testing STRING() for {dialect}"):
                query = parse_one("STRING(a)", dialect=dialect)
                self.assertEqual(query.sql(dialect), "CAST(a AS STRING)")

    def test_binary_string(self):
        for dialect in ("spark2", "spark", "databricks"):
            with self.subTest(f"Testing HEX strings for {dialect}"):
                query = parse_one("X'ab'", dialect=dialect)
                self.assertEqual(query.sql(dialect), "X'ab'")

            with self.subTest(f"Testing empty HEX strings for {dialect}"):
                query = parse_one("X''", dialect=dialect)
                self.assertEqual(query.sql(dialect), "X''")

    def test_analyze(self):
        self.validate_identity("ANALYZE TABLE tbl COMPUTE STATISTICS NOSCAN")
        self.validate_identity("ANALYZE TABLE tbl COMPUTE STATISTICS FOR ALL COLUMNS")
        self.validate_identity("ANALYZE TABLE tbl COMPUTE STATISTICS FOR COLUMNS foo, bar")
        self.validate_identity("ANALYZE TABLE ctlg.db.tbl COMPUTE STATISTICS NOSCAN")
        self.validate_identity("ANALYZE TABLES COMPUTE STATISTICS NOSCAN")
        self.validate_identity("ANALYZE TABLES FROM db COMPUTE STATISTICS")
        self.validate_identity("ANALYZE TABLES IN db COMPUTE STATISTICS")
        self.validate_identity(
            "ANALYZE TABLE ctlg.db.tbl PARTITION(foo = 'foo', bar = 'bar') COMPUTE STATISTICS NOSCAN"
        )

    def test_transpile_annotated_exploded_column(self):
        from sqlglot.optimizer.annotate_types import annotate_types
        from sqlglot.optimizer.qualify import qualify

        for db_prefix in ("", "explode_view."):
            with self.subTest(f"Annotated exploded column with prefix: {db_prefix}."):
                sql = f"""
                    WITH test_table AS (
                      SELECT
                        12345 AS id_column,
                        ARRAY(
                          STRUCT('John' AS name, 30 AS age),
                          STRUCT('Mary' AS name, 20 AS age),
                          STRUCT('Mike' AS name, 80 AS age),
                          STRUCT('Dan' AS name, 50 AS age)
                        ) AS struct_column
                    )

                    SELECT
                        id_column,
                        {db_prefix}new_column.name,
                        {db_prefix}new_column.age
                    FROM test_table
                    LATERAL VIEW EXPLODE(struct_column) explode_view AS new_column
                """

                expr = self.parse_one(sql)
                qualified = qualify(expr, dialect="spark")
                annotated = annotate_types(qualified, dialect="spark")

                self.assertEqual(
                    annotated.sql("spark"),
                    "WITH `test_table` AS (SELECT 12345 AS `id_column`, ARRAY(STRUCT('John' AS `name`, 30 AS `age`), STRUCT('Mary' AS `name`, 20 AS `age`), STRUCT('Mike' AS `name`, 80 AS `age`), STRUCT('Dan' AS `name`, 50 AS `age`)) AS `struct_column`) SELECT `test_table`.`id_column` AS `id_column`, `explode_view`.`new_column`.`name` AS `name`, `explode_view`.`new_column`.`age` AS `age` FROM `test_table` AS `test_table` LATERAL VIEW EXPLODE(`test_table`.`struct_column`) explode_view AS `new_column`",
                )
                self.assertEqual(
                    annotated.sql("presto"),
                    """WITH "test_table" AS (SELECT 12345 AS "id_column", ARRAY[CAST(ROW('John', 30) AS ROW("name" VARCHAR, "age" INTEGER)), CAST(ROW('Mary', 20) AS ROW("name" VARCHAR, "age" INTEGER)), CAST(ROW('Mike', 80) AS ROW("name" VARCHAR, "age" INTEGER)), CAST(ROW('Dan', 50) AS ROW("name" VARCHAR, "age" INTEGER))] AS "struct_column") SELECT "test_table"."id_column" AS "id_column", "explode_view"."name" AS "name", "explode_view"."age" AS "age" FROM "test_table" AS "test_table" CROSS JOIN UNNEST("test_table"."struct_column") AS "explode_view"("name", "age")""",
                )

        with self.subTest("Annotated exploded column of a previous exploded column"):
            expr = self.parse_one(
                "WITH t AS (SELECT ARRAY(STRUCT(ARRAY(1, 2) AS a)) AS arr) "
                "SELECT x FROM t LATERAL VIEW EXPLODE(arr) t1 AS s LATERAL VIEW EXPLODE(s.a) t2 AS x"
            )
            annotated = annotate_types(qualify(expr, dialect="spark"), dialect="spark")

            self.assertEqual(
                annotated.sql("presto"),
                """WITH "t" AS (SELECT ARRAY[CAST(ROW(ARRAY[1, 2]) AS ROW("a" ARRAY(INTEGER)))] AS "arr") SELECT "t2"."x" AS "x" FROM "t" AS "t" CROSS JOIN UNNEST("t"."arr") AS "t1"("a") CROSS JOIN UNNEST("t1"."a") AS "t2"("x")""",
            )

    def test_approx_percentile(self):
        self.validate_all(
            "PERCENTILE_APPROX(DISTINCT col, 0.3)",
            read={
                "spark": "APPROX_PERCENTILE(DISTINCT col, 0.3)",
                "databricks": "APPROX_PERCENTILE(DISTINCT col, 0.3)",
            },
        )
        self.validate_all(
            "PERCENTILE_APPROX(DISTINCT col, 0.3, 200)",
            read={
                "spark": "APPROX_PERCENTILE(DISTINCT col, 0.3, 200)",
                "databricks": "APPROX_PERCENTILE(DISTINCT col, 0.3, 200)",
            },
        )

        approx_quantile_expr = self.validate_identity("PERCENTILE_APPROX(DISTINCT col, 0.3)")
        approx_quantile_expr.assert_is(exp.ApproxQuantile)
        approx_quantile_expr.this.assert_is(exp.Distinct)
        approx_quantile_expr.args.get("quantile").assert_is(exp.Literal)

        approx_quantile_expr = self.validate_identity("PERCENTILE_APPROX(DISTINCT col, 0.3, 200)")
        approx_quantile_expr.assert_is(exp.ApproxQuantile)
        approx_quantile_expr.this.assert_is(exp.Distinct)
        approx_quantile_expr.args.get("quantile").assert_is(exp.Literal)
        approx_quantile_expr.args.get("accuracy").assert_is(exp.Literal)

    def test_array_insert(self):
        self.validate_all(
            "SELECT ARRAY_INSERT(ARRAY('a', 'b', 'c'), 1, 'z')",
            read={
                "databricks": "SELECT ARRAY_INSERT(ARRAY('a', 'b', 'c'), 1, 'z')",
            },
            write={
                "databricks": "SELECT ARRAY_INSERT(ARRAY('a', 'b', 'c'), 1, 'z')",
                "spark": "SELECT ARRAY_INSERT(ARRAY('a', 'b', 'c'), 1, 'z')",
                "snowflake": "SELECT ARRAY_INSERT(['a', 'b', 'c'], 0, 'z')",
            },
        )
        self.validate_all(
            "SELECT ARRAY_INSERT(ARRAY('a', 'b', 'c'), -2, 'z')",
            read={
                "snowflake": "SELECT ARRAY_INSERT(['a', 'b', 'c'], -1, 'z')",
            },
            write={
                "snowflake": "SELECT ARRAY_INSERT(['a', 'b', 'c'], -1, 'z')",
            },
        )
        self.validate_all(
            "SELECT ARRAY_INSERT(ARRAY('a', 'b', 'c'), -1, 'z')",
            write={
                "snowflake": "SELECT ARRAY_INSERT(['a', 'b', 'c'], ARRAY_SIZE(['a', 'b', 'c']), 'z')",
            },
        )
        self.validate_all(
            "SELECT ARRAY_INSERT(ARRAY('a', 'b', 'c'), 3, 'z')",
            read={
                "snowflake": "SELECT ARRAY_INSERT(['a', 'b', 'c'], 2, 'z')",
            },
        )

    def test_array_slice(self):
        self.validate_all(
            "SLICE(x, 2, 3)",
            read={
                "clickhouse": "arraySlice(x, 2, 3)",
                "presto": "SLICE(x, 2, 3)",
                "spark": "SLICE(x, 2, 3)",
            },
        )

    def test_declare(self):
        self.validate_identity("DECLARE VAR x INT", "DECLARE x INT")
        self.validate_identity("DECLARE x INT")
        self.validate_identity("DECLARE VARIABLE myvar INT DEFAULT 5", "DECLARE myvar INT = 5")
        self.validate_identity("DECLARE x, y, z INT DEFAULT 1", "DECLARE x, y, z INT = 1")
        self.validate_identity("DECLARE x INT = 5")
        self.validate_identity("DECLARE five = 5")
        self.validate_identity("DECLARE OR REPLACE five = 55")
        self.validate_identity("DECLARE VARIABLE size DEFAULT 6", "DECLARE size = 6")
        self.validate_identity("DECLARE some_var STRING")

    def test_set_variable(self):
        self.validate_all(
            "SET VAR v = 5",
            write={
                "spark": "SET VARIABLE v = 5",
                "databricks": "SET VARIABLE v = 5",
            },
        )
        self.validate_all(
            "SET VARIABLE v = 5",
            write={
                "spark": "SET VARIABLE v = 5",
                "databricks": "SET VARIABLE v = 5",
            },
        )

        self.validate_all(
            "SET VARIABLE v = (SELECT MAX(c1) FROM VALUES (1), (2) AS T(c1))",
            write={
                "spark": "SET VARIABLE v = (SELECT MAX(c1) FROM VALUES (1), (2) AS T(c1))",
                "databricks": "SET VARIABLE v = (SELECT MAX(c1) FROM VALUES (1), (2) AS T(c1))",
            },
        )

        self.validate_all(
            "SET VARIABLE v = DEFAULT",
            write={
                "spark": "SET VARIABLE v = DEFAULT",
                "databricks": "SET VARIABLE v = DEFAULT",
            },
        )

        self.validate_all(
            "SET VARIABLE v1 = 1, v2 = '2'",
            write={
                "spark": "SET VARIABLE v1 = 1, v2 = '2'",
                "databricks": "SET VARIABLE v1 = 1, v2 = '2'",
            },
        )

        self.validate_all(
            "SET VARIABLE (v1, v2) = (SELECT 1, 2)",
            write={
                "spark": "SET VARIABLE (v1, v2) = (SELECT 1, 2)",
                "databricks": "SET VARIABLE (v1, v2) = (SELECT 1, 2)",
            },
        )

    def test_try_divide(self):
        self.validate_all(
            "SELECT TRY_DIVIDE(a, b)",
            read={
                "spark": "SELECT TRY_DIVIDE(a, b)",
                "databricks": "SELECT TRY_DIVIDE(a, b)",
            },
            write={
                "spark": "SELECT TRY_DIVIDE(a, b)",
                "databricks": "SELECT TRY_DIVIDE(a, b)",
                "snowflake": "SELECT IFF(b <> 0, a / b, NULL)",
