import json
import sqlite3
import sys
import tempfile
import unittest
from concurrent.futures import ProcessPoolExecutor, as_completed, wait
from decimal import MAX_EMAX
from functools import partial
from multiprocessing import get_context
from unittest.mock import patch

import duckdb
from pandas.testing import assert_frame_equal

import sqlglot
from sqlglot import exp, optimizer, parse_one
from sqlglot.errors import ANSI_RESET, ANSI_UNDERLINE, OptimizeError, SchemaError
from sqlglot.optimizer.annotate_types import TypeAnnotator, annotate_types
from sqlglot.optimizer.canonicalize_internal_names import canonicalize_internal_names
from sqlglot.optimizer.journal import record, revert
from sqlglot.optimizer.normalize import normalization_distance
from sqlglot.optimizer.qualify import qualify
from sqlglot.optimizer.resolver import Resolver
from sqlglot.optimizer.scope import build_scope, traverse_scope, walk_in_scope
from sqlglot.schema import MappingSchema
from tests.helpers import (
    TPCDS_SCHEMA,
    TPCH_SCHEMA,
    _extract_meta,
    assert_logger_contains,
    load_sql_fixture_pairs,
    load_sql_fixtures,
    string_to_bool,
)


def parse_and_optimize(func, sql, read_dialect, **kwargs):
    optimized = func(parse_one(sql, read=read_dialect), **kwargs)

    for expression in optimized.walk():
        for arg_key, arg in expression.args.items():
            for child in arg if isinstance(arg, list) else [arg]:
                if isinstance(child, exp.Expr):
                    assert child.arg_key == arg_key, f"{child.sql()} isn't {arg_key}"
                    assert child.parent is expression, f"{child.sql()} isn't a child of its parent"

    return optimized


def qualify_then_canonicalize(expression, **qualify_kwargs):
    return canonicalize_internal_names(qualify(expression, **qualify_kwargs))


def qualify_columns(expression, validate_qualify_columns=True, **kwargs):
    expression = optimizer.qualify.qualify(
        expression,
        validate_qualify_columns=validate_qualify_columns,
        identify=False,
        **kwargs,
    )
    return expression


def pushdown_projections(expression, **kwargs):
    expression = optimizer.qualify_tables.qualify_tables(expression)
    expression = optimizer.normalize_identifiers.normalize_identifiers(
        expression, dialect=kwargs.get("dialect")
    )
    expression = optimizer.qualify_columns.qualify_columns(expression, **kwargs)
    expression = optimizer.pushdown_projections.pushdown_projections(expression)
    return expression


def normalize(expression, **kwargs):
    schema = kwargs.get("schema")

    expression = optimizer.normalize.normalize(expression, dnf=False)
    expression = annotate_types(expression, schema=schema)
    return optimizer.simplify.simplify(expression)


def simplify(expression, **kwargs):
    dialect = kwargs.get("dialect")
    schema = kwargs.get("schema")

    expression = annotate_types(expression, schema=schema, dialect=dialect)
    return optimizer.simplify.simplify(
        expression, constant_propagation=True, coalesce_simplification=True, dialect=dialect
    )


def pushdown_ctes(expression, **kwargs):
    optimizer.qualify_columns.pushdown_cte_alias_columns(build_scope(expression))
    return expression


def annotate_functions(expression, **kwargs):
    dialect = kwargs.get("dialect")
    schema = kwargs.get("schema")

    annotated = annotate_types(expression, dialect=dialect, schema=schema)

    return annotated.expressions[0]


class TestOptimizer(unittest.TestCase):
    maxDiff = None

    @classmethod
    def setUpClass(cls):
        cls.pool = ProcessPoolExecutor(mp_context=get_context("spawn"))
        cls.addClassCleanup(cls.pool.shutdown)
        sqlglot.schema = MappingSchema()
        cls.conn = duckdb.connect()
        cls.conn.execute(
            """
        CREATE TABLE x (a INT, b INT);
        CREATE TABLE y (b INT, c INT);
        CREATE TABLE z (b INT, c INT);
        CREATE TABLE w (d TEXT, e TEXT);

        INSERT INTO x VALUES (1, 1);
        INSERT INTO x VALUES (2, 2);
        INSERT INTO x VALUES (2, 2);
        INSERT INTO x VALUES (3, 3);
        INSERT INTO x VALUES (null, null);

        INSERT INTO y VALUES (2, 2);
        INSERT INTO y VALUES (2, 2);
        INSERT INTO y VALUES (3, 3);
        INSERT INTO y VALUES (4, 4);
        INSERT INTO y VALUES (null, null);

        INSERT INTO y VALUES (3, 3);
        INSERT INTO y VALUES (3, 3);
        INSERT INTO y VALUES (4, 4);
        INSERT INTO y VALUES (5, 5);
        INSERT INTO y VALUES (null, null);

        INSERT INTO w VALUES ('a', 'b');

        CREATE TABLE unpivotable (id INT, jan INT, feb INT, north INT, south INT);
        INSERT INTO unpivotable VALUES (1, 100, 200, 7, 8);
        INSERT INTO unpivotable VALUES (2, 300, 400, 9, 10);

        CREATE TABLE pivotable (id INT, cat TEXT, val INT, kind TEXT, amt INT);
        INSERT INTO pivotable VALUES (1, 'a', 10, 'x', 5);
        INSERT INTO pivotable VALUES (1, 'b', 20, 'x', 5);

        CREATE TABLE comparisons AS
        SELECT * FROM (VALUES (1), (2), (NULL)) AS x(a)
        CROSS JOIN (VALUES (1), (2), (NULL)) AS y(b)
        CROSS JOIN (VALUES (TRUE), (FALSE), (NULL)) AS z(c);
        """
        )

    def setUp(self):
        self.schema = {
            "x": {
                "a": "INT",
                "b": "INT",
            },
            # non-nullable columns, for rewrites that are only valid when a value can't be NULL
            "nn": {
                "a": exp.DataType.build("INT", nullable=False),
                "b": exp.DataType.build("INT", nullable=False),
            },
            "y": {
                "b": "INT",
                "c": "INT",
            },
            "z": {
                "b": "INT",
                "c": "INT",
            },
            "w": {
                "d": "TEXT",
                "e": "TEXT",
            },
            "temporal": {
                "d": "DATE",
                "t": "DATETIME",
            },
            "structs": {
                "one": "STRUCT<a_1 INT, b_1 VARCHAR>",
                "nested_0": "STRUCT<a_1 INT, nested_1 STRUCT<a_2 INT, nested_2 STRUCT<a_3 INT>>>",
                "quoted": 'STRUCT<"foo bar" INT>',
            },
            "t_bool": {
                "a": "BOOLEAN",
                "b": "BOOLEAN",
            },
            "comparisons": {
                "a": "INT",
                "b": "INT",
                "c": "BOOLEAN",
            },
            "unpivotable": {
                "id": "INT",
                "jan": "INT",
                "feb": "INT",
                "north": "INT",
                "south": "INT",
            },
            "pivotable": {
                "id": "INT",
                "cat": "TEXT",
                "val": "INT",
                "kind": "TEXT",
                "amt": "INT",
            },
        }

    def check_file(
        self,
        file,
        func,
        pretty=False,
        execute=None,
        only=None,
        **kwargs,
    ):
        results = {}

        for i, (meta, sql, expected) in enumerate(
            load_sql_fixture_pairs(f"optimizer/{file}.sql"), start=1
        ):
            title = meta.get("title") or f"{i}, {sql}"
            if only and title != only:
                continue

            dialect = meta.get("dialect")
            leave_tables_isolated = meta.get("leave_tables_isolated")
            validate_qualify_columns = meta.get("validate_qualify_columns")
            canonicalize_table_aliases = meta.get("canonicalize_table_aliases")
            func_kwargs = kwargs.copy()

            if schema := meta.get("schema"):
                func_kwargs["schema"] = json.loads(schema)

            if leave_tables_isolated is not None:
                func_kwargs["leave_tables_isolated"] = string_to_bool(leave_tables_isolated)

            if validate_qualify_columns is not None:
                func_kwargs["validate_qualify_columns"] = string_to_bool(validate_qualify_columns)
            if dialect:
                func_kwargs["dialect"] = dialect
            if canonicalize_table_aliases is not None:
                func_kwargs["canonicalize_table_aliases"] = string_to_bool(
                    canonicalize_table_aliases
                )

            fixture_execute = False if execute is False else meta.get("execute", execute)
            if min_python := meta.get("execute_min_python"):
                fixture_execute = string_to_bool(fixture_execute) and sys.version_info >= tuple(
                    map(int, min_python.split("."))
                )

            future = self.pool.submit(parse_and_optimize, func, sql, dialect, **func_kwargs)
            results[future] = (
                sql,
                title,
                expected,
                dialect,
                fixture_execute,
            )

        wait(results)

        for future in as_completed(results):
            sql, title, expected, dialect, execute = results[future]

            with self.subTest(title):
                optimized = future.result()
                actual = optimized.sql(pretty=pretty, dialect=dialect)
                self.assertEqual(
                    expected,
                    actual,
                )
                if string_to_bool(execute):
                    with self.subTest(f"(execute) {title}"):
                        dfs = []
                        for expression in (parse_one(sql, read=dialect), optimized):
                            if not isinstance(expression, (exp.Query, exp.Values)):
                                expression = exp.select(exp.alias_(expression, "_col_0"))
                            dfs.append(self.conn.execute(expression.sql(dialect="duckdb")).df())
                        assert_frame_equal(*dfs)

    @patch("sqlglot.generator.logger")
    def test_optimize(self, logger):
        self.assertEqual(optimizer.optimize("x = 1 + 1", identify=False).sql(), "x = 2")

        schema = {
            "x": {"a": "INT", "b": "INT"},
            "y": {"b": "INT", "c": "INT"},
            "z": {"a": "INT", "c": "INT"},
            "u": {"f": "INT", "g": "INT", "h": "TEXT"},
        }

        self.check_file(
            "optimizer",
            optimizer.optimize,
            pretty=True,
            execute=True,
            schema=schema,
        )

    def test_optimize_copy(self):
        sql = "SELECT a + 1 + 1 AS b FROM x"
        expression = parse_one(sql)
        optimized = optimizer.optimize(expression, schema=self.schema)

        self.assertIsNot(optimized, expression)
        self.assertEqual(expression.sql(), sql)
        self.assertNotEqual(optimized, expression)

        for copy in (True, False):
            with self.subTest(copy=copy):
                expression = parse_one(sql)
                result = optimizer.optimize(expression, schema=self.schema, copy=copy)
                self.assertEqual(result, optimized)
                if copy:
                    self.assertIsNot(result, expression)
                    self.assertEqual(expression.sql(), sql)
                else:
                    self.assertIs(result, expression)
                    self.assertNotEqual(expression.sql(), sql)

                self.assertEqual(optimizer.optimize(sql, schema=self.schema, copy=copy), optimized)

    def test_optimize_copy_root_replacement(self):
        expression = parse_one("1 + 1")
        optimized = optimizer.optimize(expression, copy=False)
        self.assertIsNot(optimized, expression)
        self.assertEqual(optimized.sql(), "2")

    def test_isolate_table_selects(self):
        self.check_file(
            "isolate_table_selects",
            optimizer.isolate_table_selects.isolate_table_selects,
            schema=self.schema,
        )

    def test_qualify_tables(self):
        tables = set()
        optimizer.qualify.qualify(
            parse_one("with foo AS (select * from bar) select * from foo join baz"),
            qualify_columns=False,
            on_qualify=lambda t: tables.add(t.name),
        )
        self.assertEqual(tables, {"bar", "baz"})

        # Tables referenced by lateral sources (e.g. UNNEST) must only be qualified once
        qualified = []
        optimizer.qualify_tables.qualify_tables(
            parse_one("SELECT a, x FROM t, UNNEST(arr) AS x"),
            db="db",
            catalog="c",
            on_qualify=lambda t: qualified.append(t.sql()),
        )
        self.assertEqual(qualified, ["c.db.t AS t"])

        self.assertEqual(
            optimizer.qualify.qualify(
                parse_one("WITH tesT AS (SELECT * FROM t1) SELECT * FROM test", "bigquery"),
                db="db",
                catalog="catalog",
                dialect="bigquery",
                quote_identifiers=False,
            ).sql("bigquery"),
            "WITH test AS (SELECT * FROM catalog.db.t1 AS t1) SELECT * FROM test AS test",
        )

        self.assertEqual(
            optimizer.qualify_tables.qualify_tables(
                parse_one(
                    "WITH cte AS (SELECT * FROM t) SELECT * FROM cte PIVOT(SUM(c) FOR v IN ('x', 'y'))"
                ),
                db="db",
                catalog="catalog",
            ).sql(),
            "WITH cte AS (SELECT * FROM catalog.db.t AS t) SELECT * FROM cte AS cte PIVOT(SUM(c) FOR v IN ('x', 'y')) AS _0",
        )

        self.assertEqual(
            optimizer.qualify_tables.qualify_tables(
                parse_one(
                    "WITH cte AS (SELECT * FROM t) SELECT * FROM cte PIVOT(SUM(c) FOR v IN ('x', 'y')) AS pivot_alias"
                ),
                db="db",
                catalog="catalog",
            ).sql(),
            "WITH cte AS (SELECT * FROM catalog.db.t AS t) SELECT * FROM cte AS cte PIVOT(SUM(c) FOR v IN ('x', 'y')) AS pivot_alias",
        )

        self.assertEqual(
            optimizer.qualify_tables.qualify_tables(
                parse_one("select a from b"), catalog="catalog"
            ).sql(),
            "SELECT a FROM b AS b",
        )

        self.assertEqual(
            optimizer.qualify_tables.qualify_tables(parse_one("select a from b"), db='"DB"').sql(),
            'SELECT a FROM "DB".b AS b',
        )

        self.check_file(
            "qualify_tables",
            optimizer.qualify_tables.qualify_tables,
            db="db",
            catalog="c",
        )

    def test_qualify_tables_copies_typed_alias_columns(self):
        expression = parse_one('SELECT * FROM JSON_TO_RECORDSET(z) AS y("rank" INT)')

        original = expression.find(exp.Table).args["alias"].columns[0]
        self.assertIsInstance(original, exp.ColumnDef)

        optimizer.qualify_tables.qualify_tables(expression, canonicalize_table_aliases=True)

        new = expression.find(exp.Table).args["alias"].columns[0]
        self.assertIsInstance(new, exp.ColumnDef)
        self.assertIsNot(original, new)
        self.assertEqual(original.sql(), new.sql())

    def test_normalize(self):
        self.assertEqual(
            optimizer.normalize.normalize(
                parse_one("x AND (y OR z)"),
                dnf=True,
            ).sql(),
            "(x AND y) OR (x AND z)",
        )

        self.assertEqual(
            optimizer.normalize.normalize(
                parse_one("x AND (y OR z)"),
            ).sql(),
            "x AND (y OR z)",
        )

        # Snowflake's BOOLXOR builds a Xor connector carrying a `round_input` arg, so unpacking
        # via args.values() yields 3 values. The enclosing predicate isn't normalized, which forces
        # _predicate_lengths to recurse into the Xor node.
        self.assertEqual(
            optimizer.normalize.normalize(
                parse_one("(a AND b) OR BOOLXOR(x, y)", read="snowflake"),
            ).sql(dialect="snowflake"),
            "((BOOLXOR(x, y)) OR a) AND ((BOOLXOR(x, y)) OR b)",
        )

        self.check_file("normalize", normalize, schema=self.schema)

    def test_qualify_columns_struct_field_and_source_alias(self):
        schema = {
            "customer": {
                "id": "INT",
                "address": "STRUCT<state TEXT, location STRUCT<state TEXT>>",
            },
            "addresses": {"id": "INT", "state": "TEXT"},
            "other": {"id": "INT"},
        }
        qualified = qualify(
            parse_one(
                "SELECT c.address.state FROM customer AS c "
                "JOIN addresses AS address ON c.id = address.id"
            ),
            schema=schema,
            identify=False,
        )
        struct_field = exp.Dot.build([exp.column("address", table="c"), exp.to_identifier("state")])
        self.assertEqual(qualified.find(exp.Dot), struct_field)

        nested = qualify(
            parse_one(
                "SELECT c.address.location.state FROM customer AS c "
                "CROSS JOIN addresses AS location"
            ),
            schema=schema,
            identify=False,
        )
        self.assertEqual(
            nested.find(exp.Dot),
            exp.Dot.build(
                [
                    exp.column("address", table="c"),
                    exp.to_identifier("location"),
                    exp.to_identifier("state"),
                ]
            ),
        )

        correlated = qualify(
            parse_one(
                "SELECT (SELECT c.address.state FROM addresses AS address "
                "WHERE address.id = c.id) FROM customer AS c"
            ),
            schema=schema,
            identify=False,
        )
        self.assertEqual(correlated.find(exp.Dot), struct_field)

        physical = qualify(
            parse_one(
                "SELECT db.address.state FROM db.address AS address "
                "JOIN db.other AS db ON address.id = db.id"
            ),
            schema={
                "db": {
                    "address": {"id": "INT", "state": "TEXT"},
                    "other": {"id": "INT"},
                }
            },
            identify=False,
        )
        self.assertEqual(physical.find(exp.Column), exp.column("state", table="address"))

    def test_qualify_semi_anti_join_alias_shadowing_column(self):
        for column_type, values in (
            ("STRUCT(k INT)", "(1, 10, {'k': 10}), (2, 20, {'k': 99}), (3, 30, {'k': 30})"),
            ("VARCHAR", "(1, 10, 'a'), (2, 20, 'b'), (3, 30, 'c')"),
        ):
            schema = {
                "t1": {"id": "INT", "k": "INT", "s": column_type},
                "t2": {"k": "INT", "payload": "STRUCT(k INT, nested STRUCT(k INT))"},
            }
            with duckdb.connect() as connection:
                connection.execute(f"CREATE TABLE t1 (id INT, k INT, s {column_type})")
                connection.execute(f"INSERT INTO t1 VALUES {values}")
                connection.execute(
                    "CREATE TABLE t2 (k INT, payload STRUCT(k INT, nested STRUCT(k INT)))"
                )
                connection.execute("INSERT INTO t2 VALUES (20, {'k': 20, 'nested': {'k': 20}})")

                for kind, expected in (("SEMI", [(2,)]), ("ANTI", [(1,), (3,)])):
                    for prefix, source in (
                        ("", "t2 AS s"),
                        ("", "(SELECT DISTINCT * FROM t2) AS s"),
                        ("WITH s AS (SELECT * FROM t2) ", "s"),
                    ):
                        for column in ("s.k", "s.payload.k", "s.payload.nested.k"):
                            sql = (
                                f"{prefix}SELECT t1.id FROM t1 {kind} JOIN {source} "
                                f"ON t1.k = {column}"
                            )
                            with self.subTest(column_type=column_type, sql=sql):
                                self.assertCountEqual(connection.execute(sql).fetchall(), expected)
                                for transform in (qualify, optimizer.optimize):
                                    with self.subTest(transform=transform.__name__):
                                        transformed = transform(
                                            parse_one(sql, read="duckdb"),
                                            schema=schema,
                                            dialect="duckdb",
                                        )
                                        self.assertCountEqual(
                                            connection.execute(
                                                transformed.sql("duckdb")
                                            ).fetchall(),
                                            expected,
                                        )

    def test_qualify_semi_anti_join_column_aliases(self):
        schema = {
            "t1": {"id": "INT", "k": "INT", "s": "STRUCT(v INT)"},
            "t2": {"k": "INT"},
        }
        with duckdb.connect() as connection:
            connection.execute("CREATE TABLE t1 (id INT, k INT, s STRUCT(v INT))")
            connection.execute(
                "INSERT INTO t1 VALUES (1, 10, {'v': 10}), (2, 20, {'v': 99}), (3, 30, {'v': 30})"
            )
            connection.execute("CREATE TABLE t2 (k INT)")
            connection.execute("INSERT INTO t2 VALUES (20)")

            for kind, expected in (("SEMI", [(2,)]), ("ANTI", [(1,), (3,)])):
                for prefix, source in (
                    ("", "t2 AS s(v)"),
                    ("WITH cte AS (SELECT * FROM t2) ", "cte AS s(v)"),
                ):
                    sql = f"{prefix}SELECT t1.id FROM t1 {kind} JOIN {source} ON t1.k = s.v"
                    with self.subTest(sql=sql):
                        self.assertCountEqual(connection.execute(sql).fetchall(), expected)
                        for transform in (qualify, optimizer.optimize):
                            with self.subTest(transform=transform.__name__):
                                transformed = transform(
                                    parse_one(sql, read="duckdb"), schema=schema, dialect="duckdb"
                                )
                                self.assertCountEqual(
                                    connection.execute(transformed.sql("duckdb")).fetchall(),
                                    expected,
                                )

    def test_qualify_correlated_shadowed_struct_path(self):
        schema = {
            "customer": {"address": "STRUCT<state TEXT>"},
            "other": {"id": "INT"},
            "addresses": {"id": "INT", "state": "TEXT"},
        }
        query = (
            "SELECT (SELECT c.address.state FROM other AS c "
            "JOIN addresses AS address ON c.id = address.id) AS state "
            "FROM customer AS c"
        )
        qualified = qualify(parse_one(query), schema=schema, identify=False)

        with duckdb.connect() as connection:
            connection.execute("CREATE TABLE customer (address STRUCT(state TEXT))")
            connection.execute("CREATE TABLE other (id INT)")
            connection.execute("CREATE TABLE addresses (id INT, state TEXT)")
            connection.execute("INSERT INTO customer VALUES ({'state': 'CA'})")
            connection.execute("INSERT INTO other VALUES (1)")
            connection.execute("INSERT INTO addresses VALUES (1, 'NY')")
            self.assertEqual(
                connection.execute(qualified.sql(dialect="duckdb")).fetchall(),
                connection.execute(query).fetchall(),
            )

    @patch("sqlglot.generator.logger")
    def test_qualify_columns(self, logger):
        self.assertEqual(
            optimizer.qualify.qualify(
                parse_one(
                    """
                    SELECT Teams.Name, count(*)
                    FROM raw.TeamMemberships as TeamMemberships
                    join raw.Teams
                        on Teams.Id = TeamMemberships.TeamId
