        # stale annotation caches must not prevent the new projections from being typed
        qualified = optimizer.qualify.qualify(
            parse_one(
                "WITH cte AS (SELECT t.s.* FROM t UNION ALL SELECT t.s.* FROM t) SELECT cte.x FROM cte",
