    def test_merge_asof_join_inputs(self):
        schema = {"x": {"id": "INT", "ts": "INT"}, "y": {"id": "INT", "ts": "INT", "val": "INT"}}
        with duckdb.connect() as connection:
            connection.execute(
                "CREATE TABLE x (id INT, ts INT); INSERT INTO x VALUES (1, 20), (2, 20); "
