        # that their meta (e.g. token positions) is preserved
        schema = {"cat": {"sch": {"t": {"id": "varchar", "payload": "json"}}}}
        sql = "SELECT payload.CaseSensitive FROM cat.sch.t"

        qualified = qualify(
            parse_one(sql, dialect="duckdb"),
